#!/usr/bin/env python3
"""Generate src/htspsl_data.c from the Public Suffix List."""

import argparse
import datetime
import re
import sys
import urllib.request
from pathlib import Path

URL = "https://publicsuffix.org/list/public_suffix_list.dat"
OUTPUT = Path(__file__).resolve().parent.parent / "src" / "htspsl_data.c"
END_MARKER = "// ===END PRIVATE DOMAINS==="
# MSVC refuses a string literal past 64KB, so the rules go in chunks.
CHUNK_BYTES = 60000

HEADER = """\
/* Generated by tools/psl-gen.py from
   {url}.
   Do not edit: run "python3 tools/psl-gen.py" to refresh it.

   The rules are the Public Suffix List, subject to the terms of the Mozilla
   Public License, v. 2.0. If a copy of the MPL was not distributed with this
   file, you can obtain one at https://mozilla.org/MPL/2.0/. */

#define HTS_INTERNAL_BYTECODE

#include "htspsl.h"

const char hts_psl_builtin_version[] = "{version}";

/* One rule per line keeps a refresh diff readable. */
/* clang-format off */
"""


def read_list(source):
    if re.match(r"^https?://", source):
        with urllib.request.urlopen(source, timeout=60) as reply:
            return reply.read().decode("utf-8")
    return Path(source).read_text(encoding="utf-8")


def parse(text):
    """Return (version, rules), each rule as the list spells it."""
    version = ""
    rules = []
    for line in text.splitlines():
        line = line.strip()
        match = re.match(r"^// VERSION: (\S+)", line)
        if match:
            version = match.group(1)
        if not line or line.startswith("//"):
            continue
        rules.append(line.split()[0])
    # A truncated download still has its header, but never the last line.
    if not version or END_MARKER not in text:
        sys.exit("psl-gen: this is not a complete Public Suffix List")
    return version, rules


def c_string(rule):
    """Spell a rule as a C literal, with octal escapes for non-ASCII bytes."""
    out = []
    for byte in rule.encode("utf-8"):
        if 0x20 <= byte < 0x7F and chr(byte) not in '"\\?':
            out.append(chr(byte))
        else:
            out.append("\\%03o" % byte)
    return '"' + "".join(out) + '\\0"'


def render(version, rules):
    chunks = [[]]
    size = 0
    for rule in rules:
        length = len(rule.encode("utf-8")) + 1
        if size + length > CHUNK_BYTES:
            chunks.append([])
            size = 0
        chunks[-1].append(rule)
        size += length
    out = [HEADER.format(url=URL, version=version)]
    for i, chunk in enumerate(chunks):
        out.append("\nstatic const char chunk%d[] =\n" % i)
        out.append("".join("    %s\n" % c_string(rule) for rule in chunk))
        out.append("    ;\n")
    out.append("\nconst char *const hts_psl_builtin[] = {\n")
    out.append("".join("    chunk%d,\n" % i for i in range(len(chunks))))
    out.append("    NULL,\n};\n")
    out.append("\nconst size_t hts_psl_builtin_size[] = {\n")
    out.append("".join("    sizeof(chunk%d),\n" % i for i in range(len(chunks))))
    out.append("};\n")
    out.append("/* clang-format on */\n")
    return "".join(out)


def rules_in(c_source):
    return re.findall(r'^    (".*\\0"),?$', c_source, flags=re.M)


def stamp_date(version):
    return datetime.datetime.strptime(version[:10], "%Y-%m-%d").date()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source", nargs="?", default=URL, help="list file or URL")
    parser.add_argument("output", nargs="?", default=OUTPUT, type=Path)
    parser.add_argument(
        "--check",
        type=int,
        metavar="DAYS",
        help="exit 1 when OUTPUT differs and is more than DAYS days behind",
    )
    args = parser.parse_args()
    version, rules = parse(read_list(args.source))
    text = render(version, rules)
    if args.check is not None:
        old = args.output.read_text(encoding="ascii")
        if rules_in(old) == rules_in(text):
            print("psl-gen: %s matches the list at %s" % (args.output, version))
            return 0
        built = re.search(r'hts_psl_builtin_version\[\] = "([^"]*)"', old)
        lag = stamp_date(version) - stamp_date(built.group(1))
        print(
            "psl-gen: %s differs, %d days behind %s" % (args.output, lag.days, version)
        )
        return 1 if lag.days > args.check else 0
    args.output.write_text(text, encoding="ascii")
    print("psl-gen: wrote %d rules at %s to %s" % (len(rules), version, args.output))
    return 0


if __name__ == "__main__":
    sys.exit(main())
